<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Anggota OSIS';$search=trim(isset($_GET['q'])?(string)$_GET['q']:'');$sql='SELECT a.*,u.username,u.role AS user_role FROM anggota a LEFT JOIN users u ON u.id=a.user_id';$params=[];if($search!==''){$sql.=' WHERE a.nama LIKE ? OR a.nis LIKE ? OR a.kelas LIKE ?';$like='%'.$search.'%';$params=[$like,$like,$like];}$sql.=' ORDER BY a.status ASC,a.nama ASC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$items=$stmt->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Kelola profil, status, dan akun untuk anggota OSIS.</p><div class="actions-inline"><form class="admin-search" method="get"><input name="q" value="<?=osis_e($search)?>" placeholder="Cari nama, kelas, NIS"><button type="submit">Cari</button></form><a class="button button-primary" href="<?=osis_e(osis_url('admin/anggota/tambah.php'))?>">＋ Tambah anggota</a></div></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Anggota</th><th>NIS</th><th>Kelas</th><th>Username</th><th>Peran akun</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if($items):foreach($items as $item):?><tr><td><div class="table-person"><?php if($item['foto']):?><img src="<?=osis_e(osis_image_url($item['foto']))?>" alt=""><?php else:?><span><?=osis_e(mb_strtoupper(mb_substr($item['nama'],0,1,'UTF-8'),'UTF-8'))?></span><?php endif;?><strong><?=osis_e($item['nama'])?></strong></div></td><td><?=osis_e($item['nis']?:'—')?></td><td><?=osis_e($item['kelas']?:'—')?></td><td><?=osis_e($item['username']?:'—')?></td><td><?php if($item['user_role']):?><span class="task-role-chip role-<?=osis_e($item['user_role'])?>"><?=osis_e(ucfirst($item['user_role']))?></span><?php else:?><span class="badge badge-soft">Belum ada akun</span><?php endif;?></td><td><span class="badge <?= $item['status']==='aktif'?'badge-green':'badge-soft' ?>"><?=osis_e(ucfirst($item['status']))?></span></td><td><div class="table-actions"><a class="table-action" href="<?=osis_e(osis_url('admin/anggota/edit.php?id='.(int)$item['id']))?>">Edit</a><form method="post" action="<?=osis_e(osis_url('admin/anggota/hapus.php'))?>" data-confirm="Hapus anggota ini beserta akun dan seluruh laporan/absensinya?"><?=osis_csrf_input()?><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="table-action danger-text" type="submit">Hapus</button></form></div></td></tr><?php endforeach;else:?><tr><td colspan="7" class="empty-inline">Tidak ada anggota yang ditemukan.</td></tr><?php endif;?></tbody></table></div><div class="table-footnote">Total <?=count($items)?> anggota ditampilkan.</div></div>
<?php osis_admin_page_end(); ?>
